python3 --version; ls /app/tmp; echo "---"; python3 -c "
import json
# check parse_constant behavior in 3.11
for s in ['NaN','Infinity','-Infinity','null','true','false']:
    try:
        print(s, json.loads(s, parse_constant=lambda x: ('CONST',x)))
    except Exception as e:
        print(s, 'ERR', e)
"

python3 -c "
import json
print(json.loads('1e2', parse_float=lambda x: ('F',x)))
try:
    json.loads('1.5', parse_float=lambda x: 1/0)
except Exception as e: print('err', type(e).__name__)
try:
    json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=lambda p: ('DUP',p))
except Exception as e: print('hook err', type(e).__name__)
print(json.loads('{\"a\":1,\"b\":2}', object_pairs_hook=lambda p: dict(p)))
try:
    print(json.loads('\ufeff{}'))
except Exception as e: print('bom err', type(e).__name__, e)
try:
    print(json.loads('{} x'))
except Exception as e: print('trail err', type(e).__name__)
"
